+    public void testPoint() throws IOException {
+        int z = randomIntBetween(1, 10);
+        int x = randomIntBetween(0, (1 << z) - 1);
+        int y = randomIntBetween(0, (1 << z) - 1);
+        int extent = randomIntBetween(1 << 8, 1 << 14);
